//! Native port of tests/services/eval/test_agent_runtime_eval_contract.py.
use ai_platform_gateway::migration_compat::eval_observation::validate_runtime_observation as validate;
use serde_json::{Value,json};
fn thread()->Value{json!({"thread_id":"root","runtime":{"owner":"agent_runtime"}})}
fn event(sequence:i64,kind:&str,data:Value)->Value{json!({"schema_version":"agent-event/v2","sequence":sequence,"event":{"payload":{"event_type":kind,"data":data}}})}
#[test]fn simple_and_complex_turns_have_terminal_contract(){let simple=vec![event(1,"run_started",json!({"run_id":"simple"})),event(2,"text_delta",json!({"content":"200"})),event(3,"run_finished",json!({"run_id":"simple","status":"succeeded"}))];assert!(validate(&thread(),&simple).is_empty());let complex=vec![event(1,"run_started",json!({"run_id":"complex"})),event(2,"tool_call_start",json!({"call_id":"call-1","tool_name":"search"})),event(3,"tool_call_result",json!({"call_id":"call-1","status":"succeeded"})),event(4,"tool_call_end",json!({"call_id":"call-1","status":"succeeded"})),event(5,"text_delta",json!({"content":"grounded answer"})),event(6,"run_finished",json!({"run_id":"complex","status":"succeeded"}))];assert!(validate(&thread(),&complex).is_empty());}
#[test]fn stop_and_continuation_close_tool_receipts(){let stopped=vec![event(1,"run_started",json!({"run_id":"stop"})),event(2,"tool_call_start",json!({"call_id":"call-stop","tool_name":"read"})),event(3,"tool_call_result",json!({"call_id":"call-stop","status":"cancelled"})),event(4,"tool_call_end",json!({"call_id":"call-stop","status":"cancelled"})),event(5,"run_stopped",json!({"run_id":"stop","status":"cancelled"}))];assert!(validate(&thread(),&stopped).is_empty());let continued=vec![event(5,"run_started",json!({"run_id":"resume"})),event(6,"text_delta",json!({"content":"continued"})),event(7,"run_finished",json!({"run_id":"resume","status":"succeeded"}))];assert!(validate(&thread(),&continued).is_empty());let mut orphan=stopped;orphan.remove(3);assert!(validate(&thread(),&orphan).contains(&"stopped turns must close every published tool call".into()));}
#[test]fn child_receipts_pair_exactly(){let mut events=vec![event(1,"run_started",json!({"run_id":"agent"})),event(2,"subagent_started",json!({"agent_id":"child-research"})),event(3,"subagent_finished",json!({"agent_id":"child-research","status":"succeeded"})),event(4,"text_delta",json!({"content":"merged"})),event(5,"run_finished",json!({"run_id":"agent","status":"succeeded"}))];assert!(validate(&thread(),&events).is_empty());events.remove(2);assert!(validate(&thread(),&events).contains(&"child lifecycle receipts must pair exactly".into()));}
#[test]fn compaction_requires_retention_receipt(){let mut events=vec![event(1,"run_started",json!({"run_id":"compact"})),event(2,"compaction_started",json!({})),event(3,"compaction_completed",json!({"retained_item_ids":["item-1","item-2"]})),event(4,"text_delta",json!({"content":"after compact"})),event(5,"run_finished",json!({"run_id":"compact","status":"succeeded"}))];assert!(validate(&thread(),&events).is_empty());events[2]=event(3,"compaction_completed",json!({"retained_item_ids":[]}));assert!(validate(&thread(),&events).contains(&"compaction must emit retained item ids".into()));}
#[test]fn native_context_compaction_matches_projection(){let mut events=vec![event(1,"run_started",json!({"run_id":"compact"})),event(2,"context_compaction",json!({"compacted":true})),event(3,"text_delta",json!({"content":"after compact"})),event(4,"run_finished",json!({"run_id":"compact","status":"succeeded"}))];assert!(validate(&thread(),&events).is_empty());events[1]=event(2,"context_compaction",json!({"compacted":false}));assert!(validate(&thread(),&events).contains(&"context_compaction must confirm compacted=true".into()));}
#[test]fn rejects_foreign_owner_and_orphan_result(){let errors=validate(&json!({"runtime":{"owner":"python"}}),&[event(1,"run_started",json!({"run_id":"invalid"})),event(2,"tool_call_result",json!({"call_id":"orphan","status":"succeeded"})),event(3,"run_finished",json!({"run_id":"invalid","status":"succeeded"}))]);assert!(errors.contains(&"thread.runtime.owner must be agent_runtime".into()));assert!(errors.contains(&"orphan tool results: orphan".into()));}
#[test]fn rejects_duplicate_and_reordered_sequences(){for seq in [[1,1,2],[2,1,3]]{let events=[event(seq[0],"run_started",json!({"run_id":"invalid"})),event(seq[1],"text_delta",json!({"content":"answer"})),event(seq[2],"run_finished",json!({"run_id":"invalid","status":"succeeded"}))];assert!(validate(&thread(),&events).contains(&"event sequences must be strictly increasing and unique".into()));}}
